"use client"
import { useState, useEffect } from 'react';

import { useCallback, useEffect, useRef, useState } from "react";

const [phase, setPhase] = useState<Phase>(() => {
  const store = useFingerprintStore.getState();
  if (!store.roomType) return "room_type";
  if (store.fingerprint) {
    const isConfident = store.blendRatio >= 0.72 && store.competingStyles.length <= 1;
    if (isConfident) return "compute";
    return "pairs";
  }
  return "non_visual";
});

fixes.new_str:
const [phase, setPhase] = useState<Phase>("non_visual");

useEffect(() => {
  const store = useFingerprintStore.getState();
  if (!store.roomType) { setPhase("room_type"); return; }
  if (store.fingerprint) {
    const isConfident = store.blendRatio >= 0.72 && store.competingStyles.length <= 1;
    setPhase(isConfident ? "compute" : "pairs");
    return;
  }
  setPhase("non_visual");
}, []);
